// O catálogo ativo passa a vir exclusivamente da base de dados.
CATALOG = [];
Object.keys(IMGS).forEach(function(ref){ delete IMGS[ref]; });

var BASE_PRODUCTS = {};
var BASE_IMGS = {};
var DEFAULT_CATEGORY_LABELS = [];

function syncBaseCatalogSnapshot(){
  Object.keys(BASE_PRODUCTS).forEach(function(ref){ delete BASE_PRODUCTS[ref]; });
  Object.keys(BASE_IMGS).forEach(function(ref){ delete BASE_IMGS[ref]; });
  CATALOG.forEach(function(item){
    if(item && item.ref){
      BASE_PRODUCTS[item.ref] = {
        ref: item.ref,
        name: item.name,
        type: item.type,
        cat: item.cat,
        price: item.price,
        pvp: item.pvp,
        cores: Array.isArray(item.cores) ? item.cores.slice() : [],
        tams: Array.isArray(item.tams) ? item.tams.slice() : [],
        qtdStep: inferQtyStep(item),
        active: item.active !== false,
        season: item.season || "ambos"
      };
      BASE_IMGS[item.ref] = IMGS[item.ref] || "";
    }
  });
}

function applyCatalogResponse(res, isAdminSession){
  if(!res || !Array.isArray(res.produtos)) return false;

  var labels = Array.isArray(res.categorias) && res.categorias.length
    ? res.categorias
        .filter(function(item){ return item && item.id && item.label && (isAdminSession || item.active !== false); })
        .map(function(item){ return { cat:item.id, label:item.label, active:item.active !== false }; })
    : [];
  var produtos = res.produtos.map(function(p){
    return {
      ref: p.ref,
      name: p.name,
      type: p.type || "Artigo",
      cat: p.cat,
      price: Number(p.price||0),
      pvp: p.pvp == null ? null : Number(p.pvp),
      cores: Array.isArray(p.cores) ? p.cores : [],
      tams: Array.isArray(p.tams) ? p.tams : [],
      qtdStep: inferQtyStep(p),
      active: p.active !== false,
      season: p.season || "ambos"
    };
  });
  if(!labels.length){
    var seenCats = {};
    produtos.forEach(function(item){
      if(!item || !item.cat || seenCats[item.cat]) return;
      seenCats[item.cat] = true;
      labels.push({ cat:item.cat, label:item.cat, active:true });
    });
  }

  CATALOG.length = 0;
  labels.forEach(function(item){ CATALOG.push(item); });
  produtos.forEach(function(item){ CATALOG.push(item); });

  Object.keys(IMGS).forEach(function(ref){ delete IMGS[ref]; });
  res.produtos.forEach(function(p){
    if(p.img) IMGS[p.ref] = p.img;
  });
  if(res.collectionMode){
    window.collectionMode = String(res.collectionMode || "personalizada").toLowerCase();
    try{ localStorage.setItem("villas_collection_mode", window.collectionMode); }catch(e){}
  }
  syncBaseCatalogSnapshot();
  return true;
}

function applyCategoryList(categories, preserveExistingItems){
  if(!Array.isArray(categories) || !categories.length) return false;
  var nextItems = preserveExistingItems ? CAT_ITEMS : {};
  var nextCats = categories
    .filter(function(item){ return item && item.id && item.label; })
    .map(function(item){
      var catId = item.id;
      nextItems[catId] = nextItems[catId] || [];
      return {
        id: catId,
        label: item.label,
        active: item.active !== false
      };
    });
  if(!nextCats.length) return false;
  CATS = nextCats;
  CAT_ITEMS = nextItems;
  if(!preserveExistingItems){
    syncCatalogArrayFromState();
    rebuildCatalogState();
  }
  return true;
}

function loadCatalogFromServerSync(){
  try{
    var savedToken = sessionStorage.getItem("villas_token") || localStorage.getItem("villas_token") || "";
    var savedUser = sessionStorage.getItem("villas_client") || localStorage.getItem("villas_client");
    var expiresAt = parseInt(localStorage.getItem("villas_session_expires")||"0", 10);
    var savedClient = null;
    if(savedUser && expiresAt && Date.now() < expiresAt){
      try{ savedClient = JSON.parse(savedUser); }catch(err){}
    }
    var isAdminSession = !!(savedClient && savedClient.admin);
    var xhr = new XMLHttpRequest();
    xhr.open("GET", API_BASE_URL + (isAdminSession ? "/admin/produtos" : "/produtos"), false);
    if(isAdminSession && savedToken) xhr.setRequestHeader("X-Token", savedToken);
    xhr.send(null);
    if(xhr.status === 401){
      handleSessionExpired("A sessão expirou. Volta a iniciar sessão.");
      return;
    }
    if(xhr.status < 200 || xhr.status >= 300) return;
    var res = JSON.parse(xhr.responseText||"{}");
    if(isSessionExpiredMessage(res.message)){
      handleSessionExpired(res.message);
      return;
    }
    if(!res.ok || !Array.isArray(res.produtos)) return;
    applyCatalogResponse(res, isAdminSession);
  }catch(e){}
}
loadCatalogFromServerSync();

// index by ref
var PRODS = {};
function rebuildProductIndex(){
  PRODS = {};
  CATALOG.forEach(function(p){ if(p.ref) PRODS[p.ref] = p; });
}
rebuildProductIndex();

// categories
var CATS = [], CAT_ITEMS = {};
function rebuildCatalogState(){
  rebuildProductIndex();
  CATS = [];
  CAT_ITEMS = {};
  CATALOG.forEach(function(p){
    if(p.label){
      CATS.push({id:p.cat,label:p.label,active:p.active !== false});
      CAT_ITEMS[p.cat]=CAT_ITEMS[p.cat]||[];
    }
    else {
      CAT_ITEMS[p.cat]=CAT_ITEMS[p.cat]||[];
      CAT_ITEMS[p.cat].push(p);
    }
  });
  Object.keys(CAT_ITEMS).forEach(function(catId){
    var exists = CATS.some(function(c){ return c.id===catId; });
    if(!exists){
      CATS.push({ id:catId, label:catId, active:true });
    }
  });
}
rebuildCatalogState();

if(!Object.keys(PRODS).length){
  setTimeout(function(){
    reloadCatalogFromServer()
      .then(function(){
        if(typeof refreshCatalogUi === "function") refreshCatalogUi();
        else {
          renderCatalogShell();
          if(typeof refreshCatalogVisibility === "function") refreshCatalogVisibility();
        }
      })
      .catch(function(){});
  }, 0);
}

function reloadCatalogFromServer(){
  var savedToken = sessionStorage.getItem("villas_token") || localStorage.getItem("villas_token") || "";
  var isAdminSession = !!(loggedClient && loggedClient.admin);
  return fetch(API_BASE_URL + (isAdminSession ? "/admin/produtos" : "/produtos"), {
    headers: isAdminSession && savedToken ? { "X-Token": savedToken } : {}
  })
  .then(function(r){
    return r.json().catch(function(){ return {}; }).then(function(res){
      return { status:r.status, ok:r.ok, body:res };
    });
  })
  .then(function(result){
    if(result.status === 401 || isSessionExpiredMessage(result.body && result.body.message)){
      handleSessionExpired((result.body && result.body.message) || "A sessão expirou. Volta a iniciar sessão.");
      throw new Error("A sessão expirou. Volta a iniciar sessão.");
    }
    if(!result.ok || !result.body || !result.body.ok){
      throw new Error((result.body && result.body.message) || "Nao foi possivel atualizar o catalogo.");
    }
    applyCatalogResponse(result.body, isAdminSession);
    rebuildCatalogState();
    return result.body;
  });
}

function reloadCategoriesFromServer(){
  if(!(loggedClient && loggedClient.admin)) return Promise.resolve(false);
  return fetch(API_BASE_URL + "/admin/categorias", {
    headers: { "X-Token": authToken || "" }
  })
  .then(function(r){
    return r.json().catch(function(){ return {}; }).then(function(res){
      return { status:r.status, ok:r.ok, body:res };
    });
  })
  .then(function(result){
    if(result.status === 401 || isSessionExpiredMessage(result.body && result.body.message)){
      handleSessionExpired((result.body && result.body.message) || "A sessão expirou. Volta a iniciar sessão.");
      throw new Error("A sessão expirou. Volta a iniciar sessão.");
    }
    if(!result.ok || !result.body || !result.body.ok){
      throw new Error((result.body && result.body.message) || "Nao foi possivel atualizar as categorias.");
    }
    return applyCategoryList(result.body.categorias || [], true);
  });
}

var cart = [];
var activeCat = CATS.length ? CATS[0].id : "";

var tabsEl = document.getElementById("tabs");
tabsEl.addEventListener("click", function(e){
  var btn = e.target.closest(".tab");
  if(!btn) return;
  switchCat(btn.dataset.cat);
});

var mainEl = document.getElementById("main");
var noresEl = document.getElementById("nores");
function renderCatalogShell(){
  tabsEl.innerHTML = "";
  Array.prototype.slice.call(mainEl.querySelectorAll(".sec")).forEach(function(sec){ sec.remove(); });
  var visibleCats = CATS.filter(function(cat){ return cat.active !== false; });
  if(!visibleCats.some(function(cat){ return cat.id === activeCat; }) && visibleCats.length){
    activeCat = visibleCats[0].id;
  }
  visibleCats.forEach(function(c,i){
    var btn = document.createElement("button");
    btn.className = "tab" + (c.id===activeCat || (!activeCat && i===0) ? " on":"");
    btn.textContent = c.label;
    btn.dataset.cat = c.id;
    tabsEl.appendChild(btn);

    var sec = document.createElement("section");
    sec.className = "sec" + (c.id===activeCat || (!activeCat && i===0) ? " on":"");
    sec.id = "sec_" + c.id;
    var title = document.createElement("div");
    title.className = "sec-title";
    title.innerHTML = c.label + " <small>" + (CAT_ITEMS[c.id]||[]).length + " referencias</small>";
    sec.appendChild(title);
    var grid = document.createElement("div");
    grid.className = "grid";
    (CAT_ITEMS[c.id]||[]).forEach(function(p){ grid.appendChild(mkCard(p)); });
    sec.appendChild(grid);
    mainEl.insertBefore(sec, noresEl);
  });
}
